actions.script:
                import groovy.json.JsonSlurper
                import groovy.json.JsonOutput

                String activeUserId = ec.user.getUserId() ?: "system_ide_user"
                String activeSessionId = context.sessionId ?: ec.context.sessionId

                // 🎯 A. RESOLVE TARGET URI
                String targetUri = context.artifactUri ?: ""
                if (!targetUri && targetNodeId && targetNodeId.contains("#") && targetNodeId.startsWith("component://")) {
                    targetUri = targetNodeId.split("#")[0]
                }
                if (!targetUri || targetUri.trim() == "") {
                    String rawUri = context.activeArtifactLocation ?: ec.context.activeArtifactLocation ?: context.focusCoordinate ?: ""
                    targetUri = rawUri.contains("#") ? rawUri.split("#")[0] : rawUri
                }
                if (!targetUri || targetUri.trim() == "") {
                    targetUri = (ec.context.get("activeArtifactLocation") ?: "").toString()
                }

                // 🎯 B. HYDRATE BUFFER (ADK Session State -> DB Fallback -> Disk Fallback)
                String currentMetaJsonStr = context.activeLayoutBuffer
                String bufferId = context.activeLayoutBufferId

                if (activeSessionId) {
                    try {
                        def runner = org.moqui.adk.AdkManager.runnerForSession(activeSessionId)
                        if (runner != null) {
                            def sessionOpt = runner.sessionService().getSession("moqui-adk", activeUserId, activeSessionId, java.util.Optional.empty()).blockingGet()
                            if (sessionOpt && sessionOpt.isPresent()) {
                                String stateBuffer = sessionOpt.get().state().get("activeLayoutBuffer")
                                if (stateBuffer && stateBuffer.startsWith("{")) {
                                    currentMetaJsonStr = stateBuffer
                                }
                            }
                        }
                    } catch (Exception adkEx) {
                        ec.logger.warn("⚠️ [manage#WorkspaceBuffer] Failed reading ADK Session state: ${adkEx.message}")
                    }
                }

                if (!currentMetaJsonStr || !currentMetaJsonStr.trim().startsWith("{")) {
                    if (targetUri && targetUri.trim() != "") {
                        Map bufResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.get#WorkspaceBuffer")
                            .parameters([artifactUri: targetUri, userId: activeUserId])
                            .call()
                        if (bufResult?.metaJsonBuffer) {
                            currentMetaJsonStr = bufResult.metaJsonBuffer
                            bufferId = bufResult.workspaceBufferId
                        }
                    }
                }

                // 🎯 C. PARSE BUFFER OR INITIALIZE FROM PHYSICAL XML ON DISK
                Map layoutTree = [:]
                boolean parseFailed = false

                if (currentMetaJsonStr && currentMetaJsonStr.trim().startsWith("{") && !currentMetaJsonStr.contains("[...]")) {
                    try {
                        layoutTree = new JsonSlurper().parseText(currentMetaJsonStr) as Map
                    } catch (Exception parseEx) {
                        ec.logger.warn("⚠️ [manage#WorkspaceBuffer] Invalid JSON buffer (${parseEx.message}). Reading XML from disk...")
                        parseFailed = true
                    }
                } else {
                    parseFailed = true
                }

                // 🎯 RECOVERY: Read directly from physical XML file on disk if buffer is missing
                if (parseFailed || layoutTree.isEmpty()) {
                    if (targetUri && targetUri.trim() != "") {
                        try {
                            ec.logger.info("📄 [manage#WorkspaceBuffer] Parsing physical XML file from disk: '${targetUri}'")
                            Map parseResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.parse#XmlToTree")
                                .parameter("artifactUri", targetUri)
                                .call()
                            if (parseResult?.layoutTree) {
                                layoutTree = parseResult.layoutTree as Map
                            }
                        } catch (Exception xmlEx) {
                            ec.logger.error("❌ Failed to parse physical XML file [${targetUri}]: ${xmlEx.message}")
                        }
                    }

                    if (layoutTree.isEmpty()) {
                        String screenName = targetUri ? targetUri.split("/")[-1].replace(".xml", "") : "ActiveScreen"
                        ec.logger.info("🛠️ [manage#WorkspaceBuffer] Initializing default root tree for URI: '${targetUri}'")
                        layoutTree = [
                            screen: screenName,
                            location: targetUri ?: "",
                            mariaId: screenName + "#root",
                            widgets: [
                                [
                                    _moquiTag: "form-single",
                                    "@type": "m-form-single",
                                    id: "default_form",
                                    mariaId: (targetUri ?: "") + "#default_form",
                                    children: []
                                ]
                            ]
                        ]
                    }
                }

                // 🎯 D. EXECUTE TREE MUTATION
                Map mutationResult = ec.service.sync().name("org.moqui.ai.mcp.LayoutServices.mutate#JsonTree")
                    .parameters([layoutTree: layoutTree, targetNodeId: targetNodeId, action: action, payloadNode: payloadNode])
                    .call()

                boolean isMutated = Boolean.TRUE.equals(mutationResult.mutated)
                context.mutated = isMutated

                if (isMutated) {
                    String updatedMetaJson = JsonOutput.toJson(layoutTree)

                    // 1. Persist updated tree to WorkspaceBuffer
                    ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer")
                        .parameters([
                            workspaceBufferId: bufferId,
                            artifactUri: targetUri,
                            userId: activeUserId,
                            metaJsonBuffer: updatedMetaJson
                        ])
                        .call()

//                    // 2. Compile AST and write back to physical XML on disk
//                    ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.save#ScreenXml")
//                        .parameters([
//                            artifactUri: targetUri,
//                            metaJsonBuffer: updatedMetaJson
//                        ])
//                        .call()

                    // 3. ADK Session Memory Sync
                    if (activeSessionId) {
                        try {
                            def runner = org.moqui.adk.AdkManager.runnerForSession(activeSessionId)
                            if (runner != null) {
                                def sessionOpt = runner.sessionService().getSession("moqui-adk", activeUserId, activeSessionId, java.util.Optional.empty()).blockingGet()
                                if (sessionOpt && sessionOpt.isPresent()) {
                                    sessionOpt.get().state().put("activeLayoutBuffer", updatedMetaJson)
                                }
                            }
                        } catch (Exception adkSyncEx) {
                            ec.logger.warn("⚠️ [manage#WorkspaceBuffer] ADK Session sync skipped: ${adkSyncEx.message}")
                        }
                    }

                    context.updatedMetaJson = updatedMetaJson
                    context.targetUri = targetUri
                    context.status = "SUCCESS"
                } else {
                    ec.logger.warn("❌ [manage#WorkspaceBuffer] Target container [${targetNodeId}] not found in tree.")
                    context.status = "NODE_NOT_FOUND"
                }

ec.logger.info("🚀 [TOOL EXECUTION] add#FormField -> targetNodeId=${targetNodeId}, label=${label}")
String rawName = context.name ?: "" String cleanName = (rawName.trim() != "") ? rawName.trim() : label.replaceAll("[^a-zA-Z0-9_]", "")
String resolvedUri = context.artifactUri ?: (targetNodeId.contains("#") ? targetNodeId.split("#")[0] : (context.activeArtifactLocation ?: ""))
// 🎯 1. HIPAA PHI / Medical Field Auto-Detection Set<String> sensitivePhiFields = [ "ssn", "socialsecurity", "dob", "birthdate", "medicalhistory", "diagnosis", "diagnosiscode", "prescription", "patientname", "medication", "treatmentplan", "insuranceid", "vital" ] as Set
String normalizedCheck = (cleanName + label).toLowerCase().replaceAll("[^a-z0-9]", "") boolean autoPhiEncrypt = "true".equalsIgnoreCase(context.encrypt) || sensitivePhiFields.any { normalizedCheck.contains(it) }
// 🎯 2. Build declarative field node for QMETA AST Map dynamicFieldNode = [ _moquiTag: "field", "@type": "m-field", id: java.util.UUID.randomUUID().toString(), name: cleanName, title: label, mariaId: resolvedUri + "#" + cleanName, children: [ [ _moquiTag: "text-line", "@type": "m-text-line", attributes: [ placeholder: "", disabled: "false" ], children: [] ] ] ]
if (autoPhiEncrypt) { dynamicFieldNode["encrypt"] = "true" ec.logger.info("🔒 [HIPAA Enforcement] Applied encrypt='true' on field: ${cleanName}") }
dynamicFieldNode["ai-intent"] = context.aiIntent ?: "/add-field ${cleanName}"
Map bufferResult = ec.service.sync().name("org.moqui.ai.mcp.LayoutServices.manage#WorkspaceBuffer") .parameters([ targetNodeId: targetNodeId, action: "APPEND", payloadNode: dynamicFieldNode, artifactUri: resolvedUri, activeLayoutBuffer: context.activeLayoutBuffer, activeLayoutBufferId: context.activeLayoutBufferId, activeArtifactLocation: context.activeArtifactLocation ]) .call()
context.status = bufferResult.status context.updatedMetaJson = bufferResult.updatedMetaJson

def processNode
processNode = { Map node ->
    String cleanTargetId = targetNodeId.contains("#") ? targetNodeId.split("#")[1] : targetNodeId

    boolean isTarget = (node.id == targetNodeId) || 
        (node.mariaId == targetNodeId) || 
        (node.id == cleanTargetId) ||
        (node.name == cleanTargetId) ||
        (node.screen == cleanTargetId) ||
        (node.mariaId?.toString()?.endsWith("#" + cleanTargetId))

    if (isTarget) {
        if ("APPEND".equalsIgnoreCase(action)) {
            if (node.children == null && node.widgets != null) {
                node.children = node.widgets
            }
            if (node.children == null) {
                node.children = []
            }
            node.children.add(payloadNode)
            return true
        } else if ("REPLACE".equalsIgnoreCase(action)) {
            node.clear()
            node.putAll(payloadNode)
            return true
        }
    }

    def childList = node.children ?: node.widgets
    if (childList && childList instanceof List) {
        if ("DELETE".equalsIgnoreCase(action)) {
            boolean removed = childList.removeIf { 
                it.id == targetNodeId || it.mariaId == targetNodeId || it.mariaId?.toString()?.endsWith("#" + targetNodeId)
            }
            if (removed) return true
        }
        for (child in childList) {
            if (child instanceof Map && processNode(child as Map)) return true
        }
    }
    return false
}
context.mutated = processNode(layoutTree)

import java.io.File
import groovy.io.FileType
import groovy.xml.XmlParser

List archetypeList = []
File compBase = new File("runtime/component")

if (compBase.exists() && compBase.isDirectory()) {
    compBase.eachDir { File compDir ->
        File archDir = new File(compDir, "mcp/resources/screen/archetype")
        if (archDir.exists() && archDir.isDirectory()) {
            archDir.eachFileRecurse(FileType.FILES) { File f ->
                if (!f.name.endsWith(".xml") || f.name.startsWith(".")) return

                String archName = f.name.replace(".xml", "")
                String uri = "mcp://${compDir.name}/resources/screen/archetype/${f.name}"
                String docSummary = ""

                try {
                    def root = new XmlParser(false, false).parse(f)
                    docSummary = root.attribute("description") ?: root.attribute("default-menu-title") ?: ""
                } catch (Exception ignore) {}

                archetypeList.add([
                    name       : archName,
                    uri        : uri,
                    component  : compDir.name,
                    description: docSummary ?: "Canonical ${archName} screen archetype template from ${compDir.name}"
                ])
            }
        }
    }
}

context.archetypes = archetypeList
ec.logger.info("📐 [get#ScreenArchetypeList] Discovered ${archetypeList.size()} canonical archetypes.")

import org.moqui.resource.ResourceReference

String cleanId = archetypeId.trim().replace(".xml", "").replace(".json", "")

// Check agi-ai, agi-ide, and framework locations
List candidatePaths = [
    "component://agi-ai/mcp/resources/screen/archetype/${cleanId}.xml",
    "component://agi-ide/mcp/resources/screen/archetype/${cleanId}.xml",
    "component://nursinghome/mcp/resources/screen/archetype/${cleanId}.xml"
]

ResourceReference matchedRr = null
for (String path : candidatePaths) {
    ResourceReference rr = ec.resource.getLocationReference(path)
    if (rr != null && rr.exists) {
        matchedRr = rr
        break
    }
}

if (matchedRr == null) {
    ec.logger.warn("⚠️ [get#ScreenArchetype] Archetype template '${cleanId}' not found.")
    context.status = "NOT_FOUND"
    return
}

context.status = "SUCCESS"
context.archetypeId = cleanId
context.xmlContent = matchedRr.getText()
ec.logger.info("📄 [get#ScreenArchetype] Successfully loaded archetype: ${cleanId}")
